script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';
const dlg = page.getByRole('dialog');

await step('Điều hướng vào Thiết Lập -> Cấu hình phụ trách', async () => {
  if (!page.url().includes(`/${phanHe}/`)) {
    await page.goto(`https://tasks.zuizui.io/${phanHe}/dashboard`, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const setupBtn = page.getByRole('button', { name: 'Thiết Lập' });
  if (await setupBtn.isVisible().catch(() => false)) await setupBtn.click();
  const link = page.getByRole('link', { name: 'Cấu hình phụ trách' });
  await link.waitFor({ timeout: 10000 });
  await link.click();
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
});

await step('Kiểm tra tab Theo điều kiện và dialog Thêm thiết lập', async () => {
  await page.getByText('Theo điều kiện', { exact: true }).first().click();
  const priorityBtn = page.getByRole('button', { name: /Thứ tự ưu tiên gán người phụ/ });
  if (await priorityBtn.isVisible().catch(() => false)) {
    await priorityBtn.click();
    await page.getByText(/1\. Hệ thống tìm và gán người/).waitFor({ timeout: 5000 }).catch(() => {});
  }
  const addBtn = page.getByRole('button', { name: 'Thêm mới' });
  await addBtn.waitFor({ timeout: 10000 });
  await addBtn.click();
  await dlg.waitFor({ timeout: 8000 });
  await page.getByRole('heading', { name: 'Thêm thiết lập' }).waitFor({ timeout: 8000 });
  assert(await page.getByRole('radio', { name: 'Theo Vùng miền *' }).isVisible().catch(() => false), 'Thiếu radio Theo Vùng miền');
  await page.getByRole('button', { name: 'Đóng' }).click();
  await dlg.waitFor({ state: 'hidden', timeout: 8000 }).catch(() => {});
});

await step('Kiểm tra tab Theo vị trí công việc tại cửa hàng', async () => {
  await page.getByText(/Theo vị trí công việc tại cửa/).first().click();
  await page.getByText('Vị trí công việc phụ trách phiếu').first().waitFor({ timeout: 10000 });
});

await step('Kiểm tra tab Phụ trách mặc định', async () => {
  await page.getByText('Phụ trách mặc định', { exact: true }).first().click();
  await page.getByText('Người phụ trách mặc định', { exact: true }).first().waitFor({ timeout: 10000 });
  ctx.log('Đã kiểm tra đầy đủ 3 tab của Cấu hình phụ trách.');
});
